code_snippet:
function riskyAsync() {
  setTimeout(() => {
    throw new Error('async error');
  }, 100);
}

try {
  riskyAsync();
  console.log('no error');
} catch (e) {
  console.log('caught:', e.message);
}

explanation_code:
// 비동기 오류를 올바르게 처리하려면:
async function riskyAsync() {
  return new Promise((_, reject) => {
    setTimeout(() => reject(new Error('async error')), 100);
  });
}
try {
  await riskyAsync();
} catch (e) {
  console.log('caught:', e.message); // 이제 잡힘
}

